package dev.aura.player;
import android.content.Context;import android.net.Uri;import android.content.res.AssetFileDescriptor;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.*;import java.util.concurrent.*;

/** Session-scoped LAN relay. Account credentials never leave the phone. */
@androidx.media3.common.util.UnstableApi
public final class MediaFileServer implements AutoCloseable {
    record Info(long length,String mime) {}
    interface Source {Info info()throws Exception;InputStream open(long from,long count)throws Exception;}
    private final Context context;private final ServerSocket server;private final ExecutorService pool=new ThreadPoolExecutor(3,3,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(16),new ThreadPoolExecutor.AbortPolicy());private final Map<String,Source> files=new ConcurrentHashMap<>();private final Map<String,String> paths=new ConcurrentHashMap<>();private final Set<Socket> sockets=ConcurrentHashMap.newKeySet();private final String secret;private String advertisedHost;private final java.util.function.Supplier<String> host;
    public MediaFileServer(Context c)throws Exception{this(c,()->{try{return host();}catch(Exception e){throw new IllegalStateException(e.getMessage(),e);}});}
    MediaFileServer(Context c,java.util.function.Supplier<String> host)throws Exception{context=c.getApplicationContext();this.host=host;byte[] b=new byte[24];new SecureRandom().nextBytes(b);secret=Hex.encode(b);server=new ServerSocket(0);Thread accept=new Thread(()->{while(!server.isClosed())try{Socket s=server.accept();s.setSoTimeout(10000);sockets.add(s);try{pool.execute(()->serve(s));}catch(RejectedExecutionException busy){sockets.remove(s);s.close();}}catch(IOException ignored){}},"AURA media relay");accept.setDaemon(true);accept.start();}
    public String url(Uri uri)throws Exception{return url(uri,"");}
    public synchronized String url(Uri uri,String mime)throws Exception{String address=advertisedHost;if(address==null)advertisedHost=address=host.get();String identity=uri.toString();String path=paths.get(identity);if(path==null){Source source=DriveUris.is(uri)?new DriveRelaySource(context,uri,mime):local(uri,mime);path="/"+secret+"/"+UUID.randomUUID();files.put(path,source);paths.put(identity,path);}return "http://"+address+":"+server.getLocalPort()+path;}
    String publish(Source source){String path="/"+secret+"/"+UUID.randomUUID();files.put(path,source);return "http://127.0.0.1:"+server.getLocalPort()+path;}
    private Source local(Uri uri,String hint){return new Source(){public Info info()throws Exception{try(AssetFileDescriptor afd=context.getContentResolver().openAssetFileDescriptor(uri,"r")){if(afd==null)throw new FileNotFoundException();long size=afd.getLength();if(size<0)size=afd.getParcelFileDescriptor().getStatSize();return new Info(size,MediaTypes.of(uri,hint,context.getContentResolver().getType(uri)));}}public InputStream open(long from,long count)throws Exception{AssetFileDescriptor afd=context.getContentResolver().openAssetFileDescriptor(uri,"r");if(afd==null)throw new FileNotFoundException();InputStream in=afd.createInputStream();try{long remaining=from;while(remaining>0){long n=in.skip(remaining);if(n<=0){if(in.read()<0)throw new EOFException();n=1;}remaining-=n;}return in;}catch(Exception e){in.close();throw e;}}};}
    public static String host()throws Exception{for(NetworkInterface n:Collections.list(NetworkInterface.getNetworkInterfaces()))if(n.isUp()&&!n.isLoopback()&&n.getName().startsWith("wlan"))for(InetAddress a:Collections.list(n.getInetAddresses()))if(a instanceof Inet4Address)return a.getHostAddress();throw new IOException("같은 Wi-Fi 연결이 필요합니다.");}
    private void serve(Socket socket){boolean sent=false;try(socket){BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.US_ASCII));String line=reader.readLine();if(line==null||line.length()>4096)return;String[] first=line.split(" ");if(first.length!=3)return;String range="";int total=0;for(int i=0;i<40;i++){String h=reader.readLine();if(h==null||h.isEmpty())break;if(h.length()>4096||(total+=h.length())>16384)return;if(h.toLowerCase(Locale.ROOT).startsWith("range:"))range=h.substring(6).trim();}Source source=files.get(first[1]);if(source==null){header(socket,404,"text/plain",0,-1,0);return;}if(first[0].equals("OPTIONS")){header(socket,204,"text/plain",0,-1,0);return;}if(!first[0].equals("GET")&&!first[0].equals("HEAD")){header(socket,405,"text/plain",0,-1,0);return;}Info info;try{info=source.info();}catch(Exception unavailable){header(socket,502,"text/plain",0,-1,0);return;}long length=info.length();if(length<0)throw new IOException();long from=0,to=length-1;if(!range.isEmpty()){try{if(!range.matches("bytes=\\d*-\\d*"))throw new IllegalArgumentException();String[] p=range.substring(6).split("-",-1);if(p[0].isEmpty()){long suffix=Long.parseLong(p[1]);if(suffix<=0)throw new IllegalArgumentException();from=Math.max(0,length-suffix);}else{from=Long.parseLong(p[0]);if(!p[1].isEmpty())to=Math.min(to,Long.parseLong(p[1]));}if(from>to||from>=length)throw new IllegalArgumentException();}catch(RuntimeException invalid){header(socket,416,"text/plain",0,-1,length);return;}}
        long count=Math.max(0,to-from+1);if(first[0].equals("HEAD")){header(socket,range.isEmpty()?200:206,info.mime(),count,range.isEmpty()?-1:from,length);return;}
        InputStream opened;try{opened=source.open(from,count);}catch(Exception unavailable){header(socket,502,"text/plain",0,-1,0);return;}try(InputStream in=opened){header(socket,range.isEmpty()?200:206,info.mime(),count,range.isEmpty()?-1:from,length);sent=true;byte[] buffer=new byte[32768];long remaining=count;while(remaining>0&&!socket.isClosed()){int n=in.read(buffer,0,(int)Math.min(buffer.length,remaining));if(n<0)throw new EOFException();socket.getOutputStream().write(buffer,0,n);remaining-=n;}}}
        catch(Exception error){if(!sent&&!socket.isClosed())try{header(socket,502,"text/plain",0,-1,0);}catch(IOException ignored){}}finally{sockets.remove(socket);}}
    private void header(Socket socket,int code,String type,long size,long start,long full)throws IOException{String safe=type!=null&&type.matches("[a-zA-Z0-9.+-]+/[a-zA-Z0-9.+-]+")?type:"application/octet-stream";String h="HTTP/1.1 "+code+" Response\r\nContent-Type: "+safe+"\r\nContent-Length: "+size+"\r\nAccept-Ranges: bytes\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Methods: GET, HEAD, OPTIONS\r\nAccess-Control-Allow-Headers: Range, Content-Type, Accept-Encoding\r\nAccess-Control-Expose-Headers: Content-Length, Content-Range, Accept-Ranges\r\nCache-Control: no-store\r\nConnection: close\r\n";if(start>=0)h+="Content-Range: bytes "+start+"-"+(start+size-1)+"/"+full+"\r\n";if(code==416)h+="Content-Range: bytes */"+full+"\r\n";socket.getOutputStream().write((h+"\r\n").getBytes(StandardCharsets.US_ASCII));}
    public synchronized void clear(){advertisedHost=null;files.clear();paths.clear();for(Socket socket:sockets)try{socket.close();}catch(IOException ignored){}sockets.clear();}
    @Override public void close(){clear();try{server.close();}catch(IOException ignored){}pool.shutdownNow();}
}
